import java.util.*;

class Solution {
  public List<Integer> findDisappearedNumbers(int[] nums) {
    // mark value v as seen by negating nums[v - 1]
    for (int x : nums) {
      int i = Math.abs(x) - 1;
      if (nums[i] > 0) nums[i] = -nums[i];
    }
    List<Integer> ans = new ArrayList<>();
    for (int i = 0; i < nums.length; i++) if (nums[i] > 0) ans.add(i + 1);
    return ans;
  }
}
